#[inductive(exc_check_count)]
fn exc_check_count_inductive(pre: Self, post: Self) {
    broadcast use group_multiset_axioms;

    let r = pre.exc_pending->0;

    // From ref_counts_domain: r is in domain => 0 <= r < rc_width
    assert(pre.ref_counts_domain());
    assert(0 <= r < pre.rc_width);

    // From the transition's `have ref_counts >= [r => 0]`
    assert(pre.ref_counts.index(r) == 0);

    // From shared_counts_agree:
    // 0 = shared_pending.count(r) + filter_r(shared_guard, r).len()
    // => filter_r(shared_guard, r).len() == 0
    assert(pre.shared_counts_agree());
    assert(Self::filter_r(pre.shared_guard, r).len() == 0);

    // filter_r.len() == 0 => filter_r is empty => all counts are 0
    assert(Self::filter_r(pre.shared_guard, r) =~= Multiset::<(int, T)>::empty()) by {
        lemma_multiset_empty_len(Self::filter_r(pre.shared_guard, r));
    };

    // For any x with x.0 == r: filter_r.count(x) == shared_guard.count(x)
    // (by axiom_filter_count via group_multiset_axioms)
    // And since filter_r.count(x) == 0, shared_guard.count(x) == 0
    assert forall |x: (int, T)| x.0 == r implies pre.shared_guard.count(x) == 0 by {
        assert(Self::filter_r(pre.shared_guard, r).count(x) == pre.shared_guard.count(x));
    };

    // From pre.exc_inv: no x in shared_guard has x.0 in [0, r-1]
    // Combined: no x in shared_guard has x.0 in [0, r]
    // => !(0 <= x.0 < r+1) for all x in post.shared_guard
    assert(pre.exc_inv());
    assert forall |x: (int, T)| post.shared_guard.count(x) > 0
        implies !(0 <= x.0 < r + 1) by {
        // post.shared_guard == pre.shared_guard (unchanged in transition)
        assert(pre.shared_guard.count(x) > 0);
        // from pre.exc_inv: !(0 <= x.0 < r)
        // so x.0 < 0 or x.0 >= r
        // from shared_guard_in_range: 0 <= x.0
        // so x.0 >= r
        // x.0 != r (from above)
        // so x.0 > r => !(0 <= x.0 < r+1)
        assert(pre.shared_guard_in_range());
    };
}

